import { USD, MGA } from '../../currencies';
import Big from 'big.js';
import * as fc from 'fast-check';
import {
  castToBigintCurrency,
  castToBigjsCurrency,
  createNumberDinero,
  createBigintDinero,
  createBigjsDinero,
} from 'test-utils';

import { allocate, toSnapshot } from '..';

describe('allocate', () => {
  describe('number', () => {
    const dinero = createNumberDinero;

    describe('decimal currencies', () => {
      it('allocates to percentages', () => {
        const d = dinero({ amount: 1003, currency: USD });
        const shares = allocate(d, [50, 50]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: 502,
          currency: USD,
          scale: 2,
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: 501,
          currency: USD,
          scale: 2,
        });
      });
      it('allocates to ratios', () => {
        const d = dinero({ amount: 100, currency: USD });
        const shares = allocate(d, [1, 3]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: 25,
          currency: USD,
          scale: 2,
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: 75,
          currency: USD,
          scale: 2,
        });
      });
      it('ignores zero ratios', () => {
        const d = dinero({ amount: 1003, currency: USD });
        const shares = allocate(d, [0, 50, 50]);
        const [firstAllocated, secondAllocated, thirdAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: 0,
          currency: USD,
          scale: 2,
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: 502,
          currency: USD,
          scale: 2,
        });
        expect(toSnapshot(thirdAllocated)).toEqual({
          amount: 501,
          currency: USD,
          scale: 2,
        });
      });
      it('converts the allocated amounts to the safest scale', () => {
        const d = dinero({ amount: 100, currency: USD });
        const shares = allocate(d, [
          { amount: 505, scale: 1 },
          { amount: 495, scale: 1 },
        ]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: 505,
          currency: USD,
          scale: 3,
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: 495,
          currency: USD,
          scale: 3,
        });
      });
      it('converts the ratios to the same scale before allocating', () => {
        const d = dinero({ amount: 100, currency: USD });
        const shares = allocate(d, [
          { amount: 5050, scale: 2 },
          { amount: 495, scale: 1 },
        ]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: 5050,
          currency: USD,
          scale: 4,
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: 4950,
          currency: USD,
          scale: 4,
        });
      });
      it('throws when using empty ratios', () => {
        const d = dinero({ amount: 100, currency: USD });

        expect(() => {
          allocate(d, []);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
      it('throws when using negative ratios', () => {
        const d = dinero({ amount: 100, currency: USD });

        expect(() => {
          allocate(d, [-50, -50]);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
      it('throws when using only zero ratios', () => {
        const d = dinero({ amount: 100, currency: USD });

        expect(() => {
          allocate(d, [0, 0]);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
    });
    describe('non-decimal currencies', () => {
      it('allocates to percentages', () => {
        const d = dinero({ amount: 5, currency: MGA });
        const shares = allocate(d, [50, 50]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: 3,
          currency: MGA,
          scale: 1,
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: 2,
          currency: MGA,
          scale: 1,
        });
      });
      it('allocates to ratios', () => {
        const d = dinero({ amount: 5, currency: MGA });
        const shares = allocate(d, [1, 3]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: 1,
          currency: MGA,
          scale: 1,
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: 4,
          currency: MGA,
          scale: 1,
        });
      });
      it('ignores zero ratios', () => {
        const d = dinero({ amount: 5, currency: MGA });
        const shares = allocate(d, [0, 50, 50]);
        const [firstAllocated, secondAllocated, thirdAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: 0,
          currency: MGA,
          scale: 1,
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: 3,
          currency: MGA,
          scale: 1,
        });
        expect(toSnapshot(thirdAllocated)).toEqual({
          amount: 2,
          currency: MGA,
          scale: 1,
