        });
      });
      it('converts the allocated amounts to the safest scale', () => {
        const d = dinero({ amount: new Big(100), currency: bigjsUSD });
        const shares = allocate(d, [
          { amount: new Big(505), scale: new Big(1) },
          { amount: new Big(495), scale: new Big(1) },
        ]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: new Big(505),
          currency: bigjsUSD,
          scale: new Big(3),
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: new Big(495),
          currency: bigjsUSD,
          scale: new Big(3),
        });
      });
      it('converts the ratios to the same scale before allocating', () => {
        const d = dinero({ amount: new Big(100), currency: bigjsUSD });
        const shares = allocate(d, [
          { amount: new Big(5050), scale: new Big(2) },
          { amount: new Big(495), scale: new Big(1) },
        ]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: new Big(5050),
          currency: bigjsUSD,
          scale: new Big(4),
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: new Big(4950),
          currency: bigjsUSD,
          scale: new Big(4),
        });
      });
      it('throws when using empty ratios', () => {
        const d = dinero({ amount: new Big(100), currency: bigjsUSD });

        expect(() => {
          allocate(d, []);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
      it('throws when using negative ratios', () => {
        const d = dinero({ amount: new Big(100), currency: bigjsUSD });

        expect(() => {
          allocate(d, [new Big(-50), new Big(-50)]);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
      it('throws when using only zero ratios', () => {
        const d = dinero({ amount: new Big(100), currency: bigjsUSD });

        expect(() => {
          allocate(d, [new Big(0), new Big(0)]);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
    });
    describe('non-decimal currencies', () => {
      it('allocates to percentages', () => {
        const d = dinero({ amount: new Big(5), currency: bigjsMGA });
        const shares = allocate(d, [new Big(50), new Big(50)]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: new Big(3),
          currency: bigjsMGA,
          scale: new Big(1),
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: new Big(2),
          currency: bigjsMGA,
          scale: new Big(1),
        });
      });
      it('allocates to percentages with large integers', () => {
        const d = dinero({
          amount: new Big('1000000000000000025'),
          currency: bigjsUSD,
        });
        const shares = allocate(d, [new Big(50), new Big(50)]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: new Big('500000000000000013'),
          currency: bigjsUSD,
          scale: new Big(2),
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: new Big('500000000000000012'),
          currency: bigjsUSD,
          scale: new Big(2),
        });
      });
      it('allocates to ratios', () => {
        const d = dinero({ amount: new Big(5), currency: bigjsMGA });
        const shares = allocate(d, [new Big(1), new Big(3)]);
        const [firstAllocated, secondAllocated] = shares;

        // Remainder goes to largest ratio (3) per #776
        expect(toSnapshot(firstAllocated)).toEqual({
          amount: new Big(1),
          currency: bigjsMGA,
          scale: new Big(1),
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: new Big(4),
          currency: bigjsMGA,
          scale: new Big(1),
        });
      });
      it('ignores zero ratios', () => {
        const d = dinero({ amount: new Big(5), currency: bigjsMGA });
        const shares = allocate(d, [new Big(0), new Big(50), new Big(50)]);
        const [firstAllocated, secondAllocated, thirdAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: new Big(0),
          currency: bigjsMGA,
          scale: new Big(1),
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: new Big(3),
          currency: bigjsMGA,
          scale: new Big(1),
        });
        expect(toSnapshot(thirdAllocated)).toEqual({
          amount: new Big(2),
          currency: bigjsMGA,
          scale: new Big(1),
        });
      });
      it('converts the allocated amounts to the safest scale', () => {
        const d = dinero({ amount: new Big(5), currency: bigjsMGA });
        const shares = allocate(d, [
          { amount: new Big(505), scale: new Big(1) },
          { amount: new Big(495), scale: new Big(1) },
        ]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: new Big(13),
          currency: bigjsMGA,
          scale: new Big(2),
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: new Big(12),
          currency: bigjsMGA,
          scale: new Big(2),
        });
      });
      it('converts the ratios to the same scale before allocating', () => {
        const d = dinero({ amount: new Big(5), currency: bigjsMGA });
        const shares = allocate(d, [
          { amount: new Big(5050), scale: new Big(2) },
          { amount: new Big(495), scale: new Big(1) },
        ]);
        const [firstAllocated, secondAllocated] = shares;

        expect(toSnapshot(firstAllocated)).toEqual({
          amount: new Big(64),
          currency: bigjsMGA,
          scale: new Big(3),
        });
        expect(toSnapshot(secondAllocated)).toEqual({
          amount: new Big(61),
          currency: bigjsMGA,
          scale: new Big(3),
        });
      });
      it('throws when using empty ratios', () => {
        const d = dinero({ amount: new Big(5), currency: bigjsMGA });

        expect(() => {
          allocate(d, []);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
      it('throws when using negative ratios', () => {
        const d = dinero({ amount: new Big(5), currency: bigjsMGA });

        expect(() => {
          allocate(d, [new Big(-50), new Big(-50)]);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
      it('throws when using only zero ratios', () => {
        const d = dinero({ amount: new Big(5), currency: bigjsMGA });

        expect(() => {
          allocate(d, [new Big(0), new Big(0)]);
        }).toThrowErrorMatchingInlineSnapshot(
          `[Error: [Dinero.js] Ratios are invalid.]`
        );
      });
    });
  });
  describe('properties', () => {
    const dinero = createNumberDinero;
    const safeAmount = fc.integer({ min: -100000, max: 100000 });
    const positiveRatios = fc.array(fc.integer({ min: 1, max: 100 }), {
      minLength: 1,
      maxLength: 10,
    });

    it('preserves the total: sum of shares equals the original amount', () => {
      fc.assert(
        fc.property(safeAmount, positiveRatios, (amount, ratios) => {
          const d = dinero({ amount, currency: USD });
          const shares = allocate(d, ratios);
          const total = shares.reduce(
            (sum, share) => sum + toSnapshot(share).amount,
            0
          );

          expect(total).toBe(amount);
        })
      );
    });
    it('distributes non-negatively for positive amounts', () => {
      fc.assert(
        fc.property(
          fc.integer({ min: 0, max: 100000 }),
          positiveRatios,
          (amount, ratios) => {
            const d = dinero({ amount, currency: USD });
            const shares = allocate(d, ratios);

            shares.forEach((share) => {
              expect(toSnapshot(share).amount).toBeGreaterThanOrEqual(0);
            });
          }
        )
      );
    });
  });
});

