import { USD } from '../../currencies';
import Big from 'big.js';
import * as fc from 'fast-check';
import {
  castToBigintCurrency,
  castToBigjsCurrency,
  createNumberDinero,
  createBigintDinero,
  createBigjsDinero,
} from 'test-utils';

import { equal, multiply, toSnapshot } from '..';

describe('multiply', () => {
  describe('number', () => {
    const dinero = createNumberDinero;

    it('multiplies positive Dinero objects', () => {
      const d = dinero({ amount: 400, currency: USD });

      expect(toSnapshot(multiply(d, 4))).toEqual({
        amount: 1600,
        scale: 2,
        currency: USD,
      });
      expect(toSnapshot(multiply(d, -1))).toEqual({
        amount: -400,
        scale: 2,
        currency: USD,
      });
    });
    it('multiplies negative Dinero objects', () => {
      const d = dinero({ amount: -400, currency: USD });

      expect(toSnapshot(multiply(d, 4))).toEqual({
        amount: -1600,
        scale: 2,
        currency: USD,
      });
      expect(toSnapshot(multiply(d, 1))).toEqual({
        amount: -400,
        scale: 2,
        currency: USD,
      });
    });
    it('converts the multiplied amount to the safest scale', () => {
      const d = dinero({ amount: 401, currency: USD });

      const snapshot = toSnapshot(multiply(d, { amount: 2001, scale: 3 }));

      expect(snapshot).toEqual({
        amount: 802401,
        scale: 5,
        currency: USD,
      });
    });
  });
  describe('bigint', () => {
    const dinero = createBigintDinero;
    const bigintUSD = castToBigintCurrency(USD);

    it('multiplies positive Dinero objects', () => {
      const d = dinero({ amount: 400n, currency: bigintUSD });

      expect(toSnapshot(multiply(d, 4n))).toEqual({
        amount: 1600n,
        scale: 2n,
        currency: bigintUSD,
      });
      expect(toSnapshot(multiply(d, -1n))).toEqual({
        amount: -400n,
        scale: 2n,
        currency: bigintUSD,
      });
    });
    it('multiplies negative Dinero objects', () => {
      const d = dinero({ amount: -400n, currency: bigintUSD });

      expect(toSnapshot(multiply(d, 4n))).toEqual({
        amount: -1600n,
        scale: 2n,
        currency: bigintUSD,
      });
      expect(toSnapshot(multiply(d, 1n))).toEqual({
        amount: -400n,
        scale: 2n,
        currency: bigintUSD,
      });
    });
    it('converts the multiplied amount to the safest scale', () => {
      const d = dinero({ amount: 401n, currency: bigintUSD });

      const snapshot = toSnapshot(multiply(d, { amount: 2001n, scale: 3n }));

      expect(snapshot).toEqual({
        amount: 802401n,
        scale: 5n,
        currency: bigintUSD,
      });
    });
  });
  describe('Big.js', () => {
    const dinero = createBigjsDinero;
    const bigjsUSD = castToBigjsCurrency(USD);

    it('multiplies positive Dinero objects', () => {
      const d = dinero({ amount: new Big(400), currency: bigjsUSD });

      expect(toSnapshot(multiply(d, new Big(4)))).toEqual({
        amount: new Big(1600),
        scale: new Big(2),
        currency: bigjsUSD,
      });
      expect(toSnapshot(multiply(d, new Big(-1)))).toEqual({
        amount: new Big(-400),
        scale: new Big(2),
        currency: bigjsUSD,
      });
    });
    it('multiplies negative Dinero objects', () => {
      const d = dinero({ amount: new Big(-400), currency: bigjsUSD });

      expect(toSnapshot(multiply(d, new Big(4)))).toEqual({
        amount: new Big(-1600),
        scale: new Big(2),
        currency: bigjsUSD,
      });
      expect(toSnapshot(multiply(d, new Big(1)))).toEqual({
        amount: new Big(-400),
        scale: new Big(2),
        currency: bigjsUSD,
      });
    });
    it('converts the multiplied amount to the safest scale', () => {
      const d = dinero({ amount: new Big(401), currency: bigjsUSD });

      const snapshot = toSnapshot(
        multiply(d, { amount: new Big(2001), scale: new Big(3) })
      );

      expect(snapshot).toEqual({
        amount: new Big(802401),
        scale: new Big(5),
        currency: bigjsUSD,
      });
    });
  });
  describe('properties', () => {
    const dinero = createNumberDinero;
    const safeAmount = fc.integer({ min: -100000, max: 100000 });

    it('has 1 as identity: multiply(a, 1) equals a', () => {
      fc.assert(
        fc.property(safeAmount, (a) => {
          const d = dinero({ amount: a, currency: USD });

          expect(equal(multiply(d, 1), d)).toBe(true);
        })
      );
    });
    it('by zero yields zero amount', () => {
      fc.assert(
        fc.property(safeAmount, (a) => {
          const d = dinero({ amount: a, currency: USD });
          const result = toSnapshot(multiply(d, 0)).amount;

          // JavaScript produces -0 for negative * 0, so compare with ==
          expect(result == 0).toBe(true);
        })
      );
    });
  });
});

