        // @ts-expect-error different currencies
        lessThan(d1, d2);
      }).toThrowErrorMatchingInlineSnapshot(
        `[Error: [Dinero.js] Objects must have the same currency.]`
      );
    });
  });
  describe('Big.js', () => {
