    it("doesn't crash on zero amounts", () => {
      const d = dinero({ amount: 0n, currency: bigintUSD });
      const snapshot = toSnapshot(trimScale(d));

      expect(snapshot).toMatchObject({
        amount: 0n,
        scale: 2n,
        currency: bigintUSD,
